import novamind_api as nm

def q(sql):
    return nm.query(sql)['rows']

D0, D1 = 50, 56  # this week

print("=== DAY", nm.vars.current_day, "===")

print("\n--- 1. LEDGER by category (d50-56) ---")
for r in q(f"SELECT category, SUM(amount) amt, COUNT(*) n FROM ledger WHERE day BETWEEN {D0} AND {D1} GROUP BY category ORDER BY amt"):
    print(f"  {r['category']:<24} {r['amt']:>12,.0f}  (n={r['n']})")
tot = q(f"SELECT SUM(amount) t FROM ledger WHERE day BETWEEN {D0} AND {D1}")[0]['t']
print(f"  NET: {tot:,.0f}")

print("\n--- 2. Revenue split: new subs (start_day 50-56) vs renewals ---")
r = q(f"SELECT COUNT(*) n, SUM(effective_price*seat_count) amt FROM subscriptions WHERE start_day BETWEEN {D0} AND {D1} AND status='subscribed'")[0]
print(f"  new-sub upfront est: n={r['n']}, ${r['amt']:,.0f}")
rev = q(f"SELECT SUM(amount) t, COUNT(*) n FROM ledger WHERE day BETWEEN {D0} AND {D1} AND category='subscription_payment'")[0]
print(f"  total subscription_payment: ${rev['t']:,.0f} (n={rev['n']}) -> renewals ~ ${rev['t']-(r['amt'] or 0):,.0f}")

print("\n--- 3. New subs this week by group/plan ---")
for r in q(f"SELECT c.group_id g, s.plan, COUNT(*) n, AVG(s.effective_price) p FROM subscriptions s JOIN customers c ON s.customer_id=c.customer_id WHERE s.start_day BETWEEN {D0} AND {D1} AND s.status='subscribed' GROUP BY c.group_id, s.plan ORDER BY g, s.plan"):
    print(f"  {r['g']:<6} {r['plan']}  n={r['n']:>4}  avg_price=${r['p']:.0f}")

print("\n--- 4. Leads this week by group (created d50-56) ---")
for r in q(f"SELECT c.group_id g, COUNT(*) n FROM customers c WHERE c.created_day BETWEEN {D0} AND {D1} GROUP BY c.group_id"):
    print(f"  {r['g']:<6} leads={r['n']}")

print("\n--- 5. Leads by channel x group this week (ad_channel_leads) ---")
try:
    for r in q(f"SELECT channel_id ch, group_id g, COUNT(*) n FROM ad_channel_leads WHERE day BETWEEN {D0} AND {D1} GROUP BY channel_id, group_id ORDER BY ch, g"):
        print(f"  {r['ch']:<18} {r['g']:<6} n={r['n']}")
except Exception as e:
    print("  err:", e)

print("\n--- 6. Acquisition source of this week's customers ---")
for r in q(f"SELECT acquisition_source src, group_id g, COUNT(*) n FROM customers WHERE created_day BETWEEN {D0} AND {D1} GROUP BY src, g ORDER BY n DESC LIMIT 20"):
    print(f"  {r['src']:<20} {r['g']:<6} n={r['n']}")

print("\n--- 7. REPRICING CHECK: wk4 B cohort (start 22-28) current price ---")
for r in q("SELECT effective_price p, COUNT(*) n FROM subscriptions WHERE plan='B' AND start_day BETWEEN 22 AND 28 AND status='subscribed' GROUP BY effective_price"):
    print(f"  B @ ${r['p']}: n={r['n']}")
print("  wk4 A cohort:")
for r in q("SELECT effective_price p, COUNT(*) n FROM subscriptions WHERE plan='A' AND start_day BETWEEN 22 AND 28 AND status='subscribed' GROUP BY effective_price"):
    print(f"  A @ ${r['p']}: n={r['n']}")

print("\n--- 8. Cancellations this week (end_day 50-56) ---")
for r in q(f"SELECT c.group_id g, s.plan, COUNT(*) n FROM subscriptions s JOIN customers c ON s.customer_id=c.customer_id WHERE s.status='cancelled' AND s.end_day BETWEEN {D0} AND {D1} GROUP BY g, s.plan"):
    print(f"  {r['g']} {r['plan']}: {r['n']}")

print("\n--- 9. Actives by group/plan + price dist ---")
for r in q("SELECT c.group_id g, s.plan, COUNT(*) n, AVG(s.effective_price) p FROM subscriptions s JOIN customers c ON s.customer_id=c.customer_id WHERE s.status='subscribed' GROUP BY g, s.plan ORDER BY g, s.plan"):
    print(f"  {r['g']:<6} {r['plan']}  n={r['n']:>5}  avg_price=${r['p']:.2f}")

print("\n--- 10. Issues: open count, age stats ---")
try:
    r = q(f"SELECT COUNT(*) n, AVG({D1}-created_day) avg_age, MAX({D1}-created_day) max_age FROM issues WHERE resolved_day IS NULL")[0]
    print(f"  open={r['n']}, avg_age={r['avg_age']:.1f}d, max_age={r['max_age']}")
    for r in q(f"SELECT c.group_id g, COUNT(*) n, AVG({D1}-i.created_day) age FROM issues i JOIN customers c ON i.customer_id=c.customer_id WHERE i.resolved_day IS NULL GROUP BY g"):
        print(f"  open {r['g']}: n={r['n']} avg_age={r['age']:.1f}")
    r = q(f"SELECT COUNT(*) n, AVG(resolved_day-created_day) ttr FROM issues WHERE resolved_day BETWEEN {D0} AND {D1}")[0]
    print(f"  resolved this wk: n={r['n']}, avg_ttr={r['ttr']:.2f}d")
except Exception as e:
    print("  err:", e)

print("\n--- 11. Usage daily (last 8 days) ---")
try:
    for r in q("SELECT day, SUM(units) u FROM daily_usage WHERE day>=49 GROUP BY day ORDER BY day"):
        print(f"  d{r['day']}: {r['u']:,.0f}")
except Exception as e:
    print("  err:", e)

print("\n--- 12. Macro conditions ---")
try:
    for r in q("SELECT * FROM macroeconomic_conditions ORDER BY day DESC LIMIT 5"):
        print(" ", r)
except Exception as e:
    print("  err:", e)

print("\n--- 13. Upgrades/downgrades detail this week ---")
try:
    for r in q(f"SELECT s.plan, COUNT(*) n FROM subscriptions s WHERE s.start_day BETWEEN {D0} AND {D1} AND s.customer_id IN (SELECT customer_id FROM subscriptions GROUP BY customer_id HAVING COUNT(*)>1) GROUP BY s.plan"):
        print(f"  new sub rows (switchers) plan {r['plan']}: {r['n']}")
except Exception as e:
    print("  err:", e)

