import novamind_api as nm

def q(sql):
    try:
        return nm.query(sql)['rows']
    except Exception as e:
        print("  ERR:", e)
        return []

d = nm.vars.current_day
d0, d1 = d - 7, d - 1
print(f"=== AUTO-KPI (day {d}, window d{d0}-{d1}) ===")

try:
    print("CASH:", q("SELECT SUM(amount) c FROM ledger")[0]['c'])
except Exception as e:
    print("cash err", e)

print("-- Ledger by category (last 7d) --")
for r in q(f"SELECT category, SUM(amount) amt FROM ledger WHERE day BETWEEN {d0} AND {d1} GROUP BY category ORDER BY amt"):
    print(f"  {r['category']:<24} {r['amt']:>11,.0f}")

print("-- New subs by group/plan (last 7d) --")
for r in q(f"SELECT c.group_id g, s.plan, COUNT(*) n, AVG(s.effective_price) p FROM subscriptions s JOIN customers c ON s.customer_id=c.customer_id WHERE s.start_day BETWEEN {d0} AND {d1} AND s.status='subscribed' GROUP BY g, s.plan ORDER BY g, s.plan"):
    print(f"  {r['g']:<6} {r['plan']} n={r['n']:>4} ${r['p']:.0f}")

print("-- Leads by group (last 7d) --")
for r in q(f"SELECT group_id g, COUNT(*) n FROM customers WHERE created_day BETWEEN {d0} AND {d1} GROUP BY g ORDER BY n DESC"):
    print(f"  {r['g']:<6} {r['n']}")

print("-- Leads by acquisition source (last 7d) --")
for r in q(f"SELECT acquisition_source src, group_id g, COUNT(*) n FROM customers WHERE created_day BETWEEN {d0} AND {d1} GROUP BY src, g HAVING n>3 ORDER BY n DESC LIMIT 15"):
    print(f"  {r['src']:<20} {r['g']:<6} {r['n']}")

print("-- Actives by group/plan --")
for r in q("SELECT c.group_id g, s.plan, COUNT(*) n, AVG(s.effective_price) p FROM subscriptions s JOIN customers c ON s.customer_id=c.customer_id WHERE s.status='subscribed' GROUP BY g, s.plan ORDER BY g, s.plan"):
    print(f"  {r['g']:<6} {r['plan']} n={r['n']:>5} avg=${r['p']:.2f}")

print("-- Cancels by group/plan (last 7d) --")
for r in q(f"SELECT c.group_id g, s.plan, COUNT(*) n FROM subscriptions s JOIN customers c ON s.customer_id=c.customer_id WHERE s.status='cancelled' AND s.end_day BETWEEN {d0} AND {d1} GROUP BY g, s.plan"):
    print(f"  {r['g']} {r['plan']}: {r['n']}")

print("-- Renewal-due vs paid check: cancels total --")
r = q(f"SELECT COUNT(*) n FROM subscriptions WHERE status='cancelled' AND end_day BETWEEN {d0} AND {d1}")
print("  cancels_wk:", r[0]['n'] if r else '?')

print("-- ENTERPRISE turns (open/pending!) --")
rows = q("SELECT customer_id, MAX(day) last_day, COUNT(*) msgs FROM enterprise_turns GROUP BY customer_id LIMIT 30")
if rows:
    for r in rows:
        print(f"  cust {r['customer_id']} last_msg_day={r['last_day']} msgs={r['msgs']}")
else:
    print("  (none)")

print("-- Usage (last 7d daily) --")
for r in q(f"SELECT day, SUM(usage_units) u FROM daily_usage WHERE day>={d0} GROUP BY day ORDER BY day"):
    print(f"  d{r['day']}: {r['u']:,.0f}")

print("-- Issues --")
r = q("SELECT COUNT(*) n, AVG(days_open) age FROM issues WHERE resolved_day IS NULL")
if r: print(f"  open={r[0]['n']} avg_age={r[0]['age'] if r[0]['age'] is not None else 0:.2f}")
r = q(f"SELECT COUNT(*) n, AVG(resolved_day-open_day) ttr FROM issues WHERE resolved_day BETWEEN {d0} AND {d1}")
if r and r[0]['n']: print(f"  resolved_wk={r[0]['n']} ttr={r[0]['ttr']:.2f}d")

print("-- Research projects --")
try:
    pr = nm.research.list_research_projects()
    if isinstance(pr, dict):
        for k, v in list(pr.items())[:12]:
            print(" ", k, v)
    else:
        print(" ", pr)
except Exception as e:
    print("  err:", e)

