import novamind_api as nm
import json

for g in ["S2", "E1", "D_E09", "D_S07", "D_E02"]:
    try:
        ins = nm.market.get_group_insights(group_id=g)
        print(f"\n===== {g} =====")
        # print compactly, skip long referral matrices
        if isinstance(ins, dict):
            for k, v in ins.items():
                s = json.dumps(v) if not isinstance(v, str) else v
                if len(s) > 400: s = s[:400] + "..."
                print(f"  {k}: {s}")
        else:
            print(ins)
    except Exception as e:
        print(g, "ERR", e)

