import novamind_api as nm

def q(sql):
    try:
        return nm.query(sql)['rows']
    except Exception as e:
        print("ERR:", e, "|", sql[:140]); return []

day = nm.vars.current_day
print("DAY", day)

print("\n== COLS ==")
subcols = []
for t in ["subscriptions","enterprise_turns","issues","ledger"]:
    rows = q(f"SELECT * FROM {t} LIMIT 1")
    if rows:
        print(t, "->", sorted(rows[0].keys()))
        if t == "subscriptions": subcols = list(rows[0].keys())

print("\n== USAGE BY DAY ==")
for r in q("SELECT day, SUM(usage_units) u FROM daily_usage WHERE day>=112 GROUP BY day ORDER BY day"):
    print(r['day'], f"{r['u']:>12,.0f}")

print("\n== LEDGER LAST 7D (day>=119) ==")
tot = 0
for r in q("SELECT category, SUM(amount) amt, COUNT(*) n FROM ledger WHERE day>=119 GROUP BY category ORDER BY amt"):
    print(f"{str(r['category']):>30}: {r['amt']:>12,.0f}  ({r['n']})"); tot += r['amt']
print(f"{'NET':>30}: {tot:>12,.0f}")

print("\n== ACTIVE BOOK by group/plan ==")
tb = 0
for r in q("SELECT c.group_id g, s.plan p, COUNT(*) n, SUM(s.effective_price) base, AVG(s.effective_price) avgp FROM subscriptions s JOIN customers c ON s.customer_id=c.customer_id WHERE s.status='subscribed' GROUP BY g,p ORDER BY base DESC"):
    print(f"{r['g']:>6} {r['p']}: n={r['n']:>6} base={r['base']:>12,.0f} avg={r['avgp']:.2f}"); tb += r['base']
print(f"TOTAL MONTHLY BASE: {tb:,.0f}")

sc = next((c for c in ["start_day","signup_day","created_day"] if c in subcols), None)
ec = next((c for c in ["end_day","cancel_day","cancelled_day","churn_day"] if c in subcols), None)
print("\nstart col:", sc, "| end col:", ec)

if sc:
    print("\n== LEAD OUTCOMES since d119 (group x status) ==")
    for r in q(f"SELECT c.group_id g, s.status st, COUNT(*) n, AVG(s.promotion) promo, AVG(s.effective_price) ep FROM subscriptions s JOIN customers c ON s.customer_id=c.customer_id WHERE s.{sc}>=119 GROUP BY g, st ORDER BY g, st"):
        print(f"{r['g']:>6} {r['st']:>10}: n={r['n']:>6} promo={r['promo']:.2f} ep={r['ep'] if r['ep'] is not None else -1:.2f}")
    print("\n== NEW SUBS PLAN MIX since d119 (subscribed) ==")
    for r in q(f"SELECT c.group_id g, s.plan p, COUNT(*) n, AVG(s.promotion) promo, AVG(s.effective_price) ep FROM subscriptions s JOIN customers c ON s.customer_id=c.customer_id WHERE s.{sc}>=119 AND s.status='subscribed' GROUP BY g,p ORDER BY g,p"):
        print(f"{r['g']:>6} {r['p']}: n={r['n']:>6} promo={r['promo']:.2f} ep={r['ep']:.2f}")

if ec:
    print("\n== CANCELS since d119 by group/plan ==")
    for r in q(f"SELECT c.group_id g, s.plan p, COUNT(*) n FROM subscriptions s JOIN customers c ON s.customer_id=c.customer_id WHERE s.status='cancelled' AND s.{ec}>=119 GROUP BY g,p ORDER BY n DESC"):
        print(f"{r['g']:>6} {r['p']}: {r['n']}")

print("\n== ENTERPRISE: rows day>=119 ==")
for r in q("SELECT * FROM enterprise_turns WHERE day>=119 ORDER BY day, message_id"):
    print(r)

print("\n== ENTERPRISE: latest msg per open thread ==")
rows = q("""SELECT t.customer_id cid, t.day d, t.sender snd, substr(t.content,1,110) c
FROM enterprise_turns t
JOIN (SELECT customer_id, MAX(message_id) mid FROM enterprise_turns WHERE closed=0 GROUP BY customer_id) L
ON t.customer_id=L.customer_id AND t.message_id=L.mid ORDER BY t.day DESC LIMIT 40""")
if not rows:
    rows = q("""SELECT t.customer_id cid, t.day d, t.sender snd, substr(t.content,1,110) c
FROM enterprise_turns t
JOIN (SELECT customer_id, MAX(message_id) mid FROM enterprise_turns GROUP BY customer_id) L
ON t.customer_id=L.customer_id AND t.message_id=L.mid ORDER BY t.day DESC LIMIT 40""")
for r in rows: print(r)

print("\n== ISSUES ==")
for r in q("SELECT c.group_id g, COUNT(*) n FROM issues i JOIN customers c ON i.customer_id=c.customer_id WHERE i.resolved_day IS NULL GROUP BY g ORDER BY n DESC"):
    print(f"{r['g']:>6}: {r['n']}")

print("\n== R&D ==")
try:
    for p in nm.research.list_research_projects():
        print(p)
except Exception as e:
    print("ERR research:", e)

print("\n== MARKET OVERVIEW ==")
try:
    ov = nm.market.get_market_overview()
    print(ov)
except Exception as e:
    print("ERR overview:", e)

