import novamind_api as nm, json

def sec(t): print("\n==== " + t + " ====")

print("DAY", nm.vars.current_day)

sec("ENTERPRISE TURNS (last 30 msgs)")
try:
    r = nm.query("SELECT * FROM enterprise_turns ORDER BY message_id DESC LIMIT 30")
    rows = r['rows']
    if rows:
        print("COLS:", list(rows[0].keys()))
    for row in reversed(rows):
        print(json.dumps(row)[:600])
except Exception as e:
    print("ERR", e)

sec("NEW CUSTOMERS since d127 by group/status")
try:
    r = nm.query("SELECT c.group_id, s.status, COUNT(*) n FROM subscriptions s JOIN customers c ON s.customer_id=c.customer_id WHERE s.start_day>=127 GROUP BY c.group_id, s.status ORDER BY c.group_id")
    for row in r['rows']: print(row)
except Exception as e: print("ERR", e)

sec("NEW SUBS plan mix since d127")
try:
    r = nm.query("SELECT c.group_id, s.plan, COUNT(*) n, ROUND(AVG(s.price),2) avgp FROM subscriptions s JOIN customers c ON s.customer_id=c.customer_id WHERE s.start_day>=127 AND s.status='subscribed' GROUP BY c.group_id, s.plan")
    for row in r['rows']: print(row)
except Exception as e: print("ERR", e)

sec("ACTIVE BOOK by group/plan")
try:
    r = nm.query("SELECT c.group_id, s.plan, COUNT(*) n, ROUND(AVG(s.price),2) avgp, ROUND(SUM(s.price),0) base FROM subscriptions s JOIN customers c ON s.customer_id=c.customer_id WHERE s.status='subscribed' GROUP BY c.group_id, s.plan ORDER BY base DESC")
    tot=0
    for row in r['rows']:
        print(row); tot+=row['base']
    print("TOTAL MONTHLY BASE:", tot)
except Exception as e: print("ERR", e)

sec("CANCELS since d127 by group/plan")
try:
    r = nm.query("SELECT c.group_id, s.plan, COUNT(*) n FROM subscriptions s JOIN customers c ON s.customer_id=c.customer_id WHERE s.status='cancelled' AND s.end_day>=127 GROUP BY c.group_id, s.plan")
    for row in r['rows']: print(row)
except Exception as e: print("ERR", e)

sec("LEDGER cols")
try:
    r = nm.query("SELECT * FROM ledger ORDER BY day DESC LIMIT 2")
    print("LEDGER COLS:", list(r['rows'][0].keys()))
    for row in r['rows']: print(json.dumps(row)[:300])
except Exception as e: print("ERR", e)

sec("LEDGER since d127 by type")
try:
    r = nm.query("SELECT type, COUNT(*) n, ROUND(SUM(amount),0) total FROM ledger WHERE day>=127 GROUP BY type ORDER BY total")
    for row in r['rows']: print(row)
except Exception as e: print("ERR", e)

sec("PAYMENT amount histogram since d127 (top 15)")
try:
    r = nm.query("SELECT ROUND(amount,2) amt, COUNT(*) n, ROUND(SUM(amount),0) tot FROM ledger WHERE day>=127 AND amount>0 GROUP BY ROUND(amount,2) ORDER BY n DESC LIMIT 15")
    for row in r['rows']: print(row)
except Exception as e: print("ERR", e)

sec("ISSUES")
try:
    r = nm.query("SELECT * FROM issues LIMIT 2")
    print("ISSUE COLS:", list(r['rows'][0].keys()))
except Exception as e: print("ERR", e)
try:
    r = nm.query("SELECT status, COUNT(*) n FROM issues GROUP BY status")
    for row in r['rows']: print(row)
except Exception as e: print("ERR", e)

sec("MARKET OVERVIEW")
try:
    ov = nm.market.get_market_overview()
    print(json.dumps(ov)[:4500])
except Exception as e: print("ERR", e)

sec("S2 INSIGHTS")
try:
    gi = nm.market.get_group_insights(group_id="S2")
    print(json.dumps(gi)[:2500])
except Exception as e: print("ERR", e)

sec("RESEARCH PROJECTS")
try:
    pr = nm.research.list_research_projects()
    print(json.dumps(pr)[:4500])
except Exception as e: print("ERR", e)

