arguments.content:
import novamind_api as nm

print("--- New-cohort (start_day>140) by status ---")
r = nm.query("SELECT status, COUNT(*) n FROM subscriptions WHERE start_day > 140 GROUP BY status")
for row in r['rows']: print(row)

print("\n--- New subs (start_day>140, subscribed/cancelled) by plan & listed price ---")
r = nm.query("SELECT plan, listed_price, COUNT(*) n FROM subscriptions WHERE start_day > 140 AND status IN ('subscribed','cancelled') GROUP BY plan, listed_price ORDER BY n DESC LIMIT 15")
for row in r['rows']: print(row)

print("\n--- Book by plan & listed price (all subscribed) ---")
r = nm.query("SELECT plan, listed_price, COUNT(*) n FROM subscriptions WHERE status='subscribed' GROUP BY plan, listed_price ORDER BY n DESC LIMIT 15")
for row in r['rows']: print(row)

print("\n--- Subs by group ---")
r = nm.query("SELECT c.group_id, COUNT(*) n FROM subscriptions s JOIN customers c ON s.customer_id=c.customer_id WHERE s.status='subscribed' GROUP BY c.group_id ORDER BY n DESC")
for row in r['rows']: print(row)

print("\n--- Cancels this week by group ---")
r = nm.query("SELECT c.group_id, s.plan, COUNT(*) n FROM subscriptions s JOIN customers c ON s.customer_id=c.customer_id WHERE s.status='cancelled' AND s.end_day > 140 GROUP BY c.group_id, s.plan ORDER BY n DESC LIMIT 12")
for row in r['rows']: print(row)

print("\n--- Daily usage last 8 days ---")
r = nm.query("SELECT day, SUM(units) u FROM daily_usage WHERE day > 139 GROUP BY day ORDER BY day")
for row in r['rows']: print(row)

