import novamind_api as nm
CASH0 = 13050.295

r = nm.query("""SELECT plan, billing_day_mod30 bdm, COUNT(*) n, SUM(effective_price) amt
    FROM subscriptions WHERE status='subscribed' AND start_day<380 GROUP BY plan, bdm""")
book = {(row['plan'], row['bdm']): [row['n']*1.0, row['amt']*1.0] for row in r['rows']}
r = nm.query("""SELECT plan, billing_day_mod30 bdm, COUNT(*) n, SUM(effective_price) amt
    FROM subscriptions WHERE status='subscribed' AND start_day>=380 GROUP BY plan, bdm""")
fresh = {(row['plan'], row['bdm']): [row['n']*1.0, row['amt']*1.0] for row in r['rows']}

WEEKS = list(range(441, 505, 7))
OPS = {441:220,448:190,455:170,462:150,469:140,476:130,483:120,490:60,497:45,504:35}

def run(name, fC, fB, dev_wk, cps=14.2, verbose=True):
    st = {k:[v[0],v[1]] for k,v in book.items()}
    fr = {k:[v[0],v[1]] for k,v in fresh.items()}
    cash = CASH0; out={}
    if verbose: print(f"--- {name} ---")
    for we in WEEKS:
        paid=0.0; sched=0.0; subdays=0.0
        for d in range(we-6, we+1):
            m=d%30
            for (p,b),v in st.items():
                if b==m and v[1]>0:
                    F=fC(we) if p=='C' else fB(we); sched+=v[1]; paid+=v[1]*F; v[0]*=F; v[1]*=F
            for (p,b),v in fr.items():
                if b==m and v[1]>0:
                    paid+=v[1]*0.20; v[0]*=0.20; v[1]*=0.20
            subdays += sum(x[0] for x in st.values())+sum(x[0] for x in fr.values())
        sa=subdays/7; compute=sa*cps/1000; adrev=sa*0.594/1000; dev=dev_wk(we)
        net=paid/1000+adrev-OPS[we]-dev-28-compute-0.3
        cash+=net; out[we]=cash
        if verbose: print(f"  d{we}: sched={sched/1000:6.1f} paid={paid/1000:6.1f} subs={sa:6.0f} net={net:+7.1f} cash={cash:8.1f}")
    return out

const=lambda x:(lambda we:x)
# F_C declining central: 0.79 -> 0.77 over 10 weeks (cluster bites, no dev defense)
def fc_central(we):
    i=WEEKS.index(we); return 0.79 - 0.02*(i/9)
def fb_central(we):
    i=WEEKS.index(we); return max(0.15, 0.25 - 0.01*i)
devcut=const(0)

print("=== CENTRAL: F_C 0.79->0.77, dev CUT ===")
c=run("CENTRAL", fc_central, fb_central, devcut)
print("\n=== DOWN: F_C 0.74 flat (cluster bites hard) ===")
dn=run("DOWN", const(0.74), const(0.15), devcut, verbose=False)
print("=== UP: F_C 0.82 flat (cluster=noise) ===")
up=run("UP", const(0.82), const(0.32), devcut, verbose=False)
print(f"d504: DOWN={dn[504]:.0f} CENTRAL={c[504]:.0f} UP={up[504]:.0f}")
print("\n=== ANCHORS (dev cut) ===")
for lbl,we in [("1wk d441",441),("4wk d462",462),("d504 TERM",504)]:
    print(f"{lbl}: {c[we]:.0f}  [{dn[we]:.0f}, {up[we]:.0f}]")
