./novamind-operation python-c "
import novamind_api as nm, json
r = nm.query(\"SELECT plan, billing_day_mod30 as mod, COUNT(*) as n, SUM(effective_price) as mrr FROM subscriptions WHERE status='subscribed' GROUP BY plan, billing_day_mod30 ORDER BY plan, mod\")
buckets = {}
for row in r['rows']:
    buckets[f\"{row['plan']}_{row['mod']}\"] = {'n': row['n'], 'mrr': row['mrr']}
json.dump(buckets, open('buckets_d455.json','w'), indent=1)
# weekly due (d456-462 = mods 6-12, etc)
def wk_due(mods):
    c = sum(buckets.get(f'C_{m}',{'mrr':0})['mrr'] for m in mods)
    b = sum(buckets.get(f'B_{m}',{'mrr':0})['mrr'] for m in mods)
    nn = sum(buckets.get(f'C_{m}',{'n':0})['n']+buckets.get(f'B_{m}',{'n':0})['n'] for m in mods)
    return c, b, nn
wks = {'wk66 d456-462': [6,7,8,9,10,11,12], 'wk67 d463-469': [13,14,15,16,17,18,19], 'wk68 d470-476': [20,21,22,23,24,25,26], 'wk69 d477-483': [27,28,29,0,1,2,3], 'wk70 d484-490': [4,5,6,7,8,9,10], 'wk71 d491-497': [11,12,13,14,15,16,17], 'wk72 d498-504': [18,19,20,21,22,23,24]}
for k, mods in wks.items():
    c,b,n = wk_due(mods)
    print(f'{k}: C_due={c:,.0f} B_due={b:,.0f} subs={n}')
print('total book:', sum(v['mrr'] for v in buckets.values()))
"

