import novamind_api as nm

# ===== 1) CRITICAL: RESTORE C=5 (applies d491; mod-11 bills d491 at T5) =====
r = nm.pricing.set_model_tiers(A=2, B=3, C=5)
print('TIERS RESTORED:', r)

# ===== 2) F70: m4-10 dip bucket outcome (baseline 325 subs / 52,115 dues) =====
try:
    q = nm.query(\"SELECT status, COUNT(*) n, ROUND(SUM(effective_price),2) dues FROM subscriptions WHERE plan='C' AND billing_day_mod30 BETWEEN 4 AND 10 AND (status='subscribed' OR (status='cancelled' AND end_day BETWEEN 484 AND 490)) GROUP BY status\")
    print('F70 m4-10:', q['rows'])
except Exception as e: print('ERR F70', e)

try:
    q = nm.query(\"SELECT billing_day_mod30 m, COUNT(*) n FROM subscriptions WHERE status='cancelled' AND end_day BETWEEN 484 AND 490 GROUP BY m ORDER BY m\")
    print('cancels by mod:', q['rows'])
except Exception as e: print('ERR cbm', e)

# ===== 3) Ledger wk70 verify =====
try:
    q = nm.query(\"SELECT category, ROUND(SUM(amount),2) amt, COUNT(*) n FROM ledger WHERE day BETWEEN 484 AND 490 GROUP BY category ORDER BY category\")
    print('LEDGER wk70:', q['rows'])
except Exception as e: print('ERR ledger', e)

# ===== 4) Buckets for wk71/wk72 =====
try:
    q = nm.query(\"SELECT CASE WHEN billing_day_mod30 BETWEEN 11 AND 17 THEN 'wk71_m11_17' WHEN billing_day_mod30 BETWEEN 18 AND 24 THEN 'wk72_m18_24' WHEN billing_day_mod30 BETWEEN 25 AND 26 THEN 'post_freeze_m25_26' ELSE 'other' END b, COUNT(*) n, ROUND(SUM(effective_price),2) dues FROM subscriptions WHERE status='subscribed' GROUP BY b\")
    print('BUCKETS:', q['rows'])
except Exception as e: print('ERR buckets', e)

# ===== 5) Issues: arrivals / resolutions / backlog age =====
try:
    q = nm.query('SELECT COUNT(*) n FROM issues WHERE open_day BETWEEN 484 AND 490')
    print('arrivals wk70:', q['rows'])
    q = nm.query('SELECT COUNT(*) n, ROUND(AVG(resolved_day-open_day),2) avg_d FROM issues WHERE resolved_day BETWEEN 484 AND 490')
    print('resolved wk70:', q['rows'])
    q = nm.query('SELECT open_day, COUNT(*) n FROM issues WHERE resolved_day IS NULL GROUP BY open_day ORDER BY open_day')
    print('backlog by open_day:', q['rows'])
except Exception as e: print('ERR issues', e)

# ===== 6) Event scan: posts d484-490 =====
try:
    q = nm.query('SELECT day, COUNT(*) n FROM social_media_posts WHERE day BETWEEN 484 AND 490 GROUP BY day ORDER BY day')
    print('posts/day:', q['rows'])
except Exception as e: print('ERR ppd', e)
